	s = stripComment(s)
	if len(s) < 2 || s[len(s)-1] != '}' {
		return nil, fmt.Errorf("unterminated inline table")
	}
	o := Object{}
	for _, item := range mustSplit(s[1 : len(s)-1]) {
		p, e := assignmentEquals(item)
		if e != nil {
			return nil, e
		}
		k, e := parseKey(item[:p])
		if e != nil || len(k) == 0 {
			return nil, fmt.Errorf("invalid inline key")
		}
		target := o
		for _, part := range k[:len(k)-1] {
			next, ok := target[part].(Object)
			if !ok {
				if target[part] != nil {
					return nil, fmt.Errorf("duplicate key")
				}
				next = Object{}
				target[part] = next
			}
			target = next
		}
		if _, ok := target[k[len(k)-1]]; ok {
			return nil, fmt.Errorf("duplicate key")
		}
		v, e := parseValue(strings.TrimSpace(item[p+1:]))
		if e != nil {
			return nil, e
		}
		target[k[len(k)-1]] = v
	}
	return o, nil
}
func mustSplit(s string) []string { x, _ := splitItems(s); return x }
